    _updateTestReview(){const d=this.shadowRoot.getElementById('dialog'),c=this._assigned(this._testSlot),box=d.querySelector('#test-review');if(!box||!c)return;const type=d.querySelector('[name="test_type"]:checked')?.value||'quality';const current=Math.min(Number(c.discharge_current),Number(c.capacity_mah)/5000,2);box.innerHTML=this._html`<dl class="review"><dt>Charge limit</dt><dd>${this._number(c.charge_current)} A · ${this._number(c.charge_voltage/1000,3)} V</dd><dt>Discharge${type==='ir'?'':this._t(', 0.2C')}</dt><dd>up to ${this._number(type==='ir'?Math.min(.5,Number(c.discharge_current)):current)} A · ${this._number(c.discharge_voltage/1000,3)} V</dd><dt>Storage</dt><dd>${c.storage_voltage?this._html`${this._number(c.storage_voltage/1000,3)} V`:this._t("Not supported for this chemistry")}</dd></dl>${type==='quality'?this._t("<ol class=\"sequence\"><li>Charge → rest for 30 min</li><li>Measure capacity → rest for 30 min</li><li>Recharge → rest for 30 min</li><li>Measure resistance → storage</li><li>Rest for 1 hour → measure voltage drift for 24 hours</li></ol><p class=\"note\">The full test takes more than a day. Keep the cell in the same slot between stages. After HA restarts, the test requires an explicit resume.</p>"):type==='capacity'?this._t("<p class=\"note\">This test measures actual capacity by controlled discharge. Duration depends on capacity and current.</p>"):this._t("<p class=\"note\">Resistance depends on temperature, state of charge and slot contact. Compare measurements taken under the same conditions.</p>")}`;}
    async _resume(slot){const job=this._jobs[String(slot)];if(!job||job.state!=='paused'||this._stopPending(slot))return;const repeat=job.phase==='discharge'?this._t(" An interrupted discharge will be repeated after a full charge."):'';if(!await this._confirm(this._t("Resume this test?"),this._html`Slot ${slot}: ${job.cell_name||this._assigned(slot)?.name||this._t("cell")}. Confirm that the cell has not changed and the cause of the pause has been resolved.${repeat}`,this._t("Resume test")))return;if(this._jobs[String(slot)]?.id!==job.id||this._jobs[String(slot)]?.state!=='paused'||this._stopPending(slot))return;await this._call('resume_quality_test',{slots:[slot]},this._t("Resume requested. Check the test state in the slot card."));}
